/* Illustrative authorization flow. No provider requests or credentials. */
const demoConnections={};
try{const saved=JSON.parse(sessionStorage.getItem('srs-ad-connections')||'{}');for(const k of accountKeys())if(['Reporting only','Campaign management'].includes(saved[k]))demoConnections[k]=saved[k]}catch(e){}
let connectionFlow;
function persistConnections(){try{sessionStorage.setItem('srs-ad-connections',JSON.stringify(demoConnections))}catch(e){}}
function connectDemo(p){connectionFlow={platform:p,step:1,access:'Reporting only',selected:[]};modal(`Connect ${p} Ads`,'Interactive authorization walkthrough · simulation only','');drawConnection()}
function drawConnection(){const f=connectionFlow;const keys=accountKeys().filter(k=>k.startsWith(f.platform+' / '));const body=$('#dialog .modal-body');body.innerHTML=`<div class="connection-disclosure">SRS Logics demo · Not a ${esc(f.platform)} sign-in page. No password or real account access is requested.</div><div class="wizard-progress">${['Authorize','Select accounts','Complete'].map((x,i)=>`<div class="${f.step===i+1?'current':f.step>i+1?'done':''}"><span>${f.step>i+1?'✓':i+1}</span>${x}</div>`).join('')}</div>${f.step===1?`<div class="connection-identity">${platform(f.platform)}<div><strong>Sample business administrator</strong><small>Northstar Collective · fictional identity</small></div></div><h3>Review application access</h3><p class="sub">In production, the platform’s own authorization page asks you to approve access. This screen illustrates that step.</p><label>Permission level<select id="connection-access"><option ${f.access==='Reporting only'?'selected':''}>Reporting only</option><option ${f.access==='Campaign management'?'selected':''}>Campaign management</option></select></label><ul class="permission-list"><li>View accounts you are permitted to access</li><li>Read campaign performance and reporting</li><li id="write-permission">${f.access==='Campaign management'?'Create and update campaigns and budgets':'No permission to change campaigns or budgets'}</li></ul><p class="note">Illustrative permission groups; exact scopes depend on the platform. VPN access is separate.</p><div class="modal-actions"><button data-connect="deny">Decline</button><button class="primary" data-connect="authorize">Approve sample access </button></div>`:f.step===2?`<h3>Choose advertising accounts</h3><p class="sub">${esc(f.access)} · Choose at least one sample account to link.</p><div class="connection-accounts">${keys.map(k=>`<label><input type="checkbox" name="connection-account" value="${esc(k)}" ${f.selected.includes(k)?'checked':''}><span><strong>${esc(k.split(' / ')[1])}</strong><small>${esc(f.platform)} Ads · INR · ${demoConnections[k]?'Already linked in demo':'Sample account'}</small></span></label>`).join('')}</div><div id="connection-error" role="alert"></div><div class="modal-actions"><button data-connect="back">← Back</button><button class="primary" data-connect="finish">Connect selected accounts </button></div>`:`<div class="connection-success"><span>✓</span><h3>${f.selected.length} sample account${f.selected.length===1?'':'s'} connected</h3><p>Your selected accounts now show their demo connection status in the workspace.</p></div><dl class="detail-list"><div><dt>Access</dt><dd>${esc(f.access)}</dd></div><div><dt>Initial sync</dt><dd>Sample data ready</dd></div><div><dt>Real platform connection</dt><dd>Not established</dd></div></dl><div class="modal-actions"><button class="primary" data-connect="done">View connected accounts </button></div>`}`;body.querySelector('select,input,button')?.focus()}
const previousAccounts=views.accounts;
views.accounts=function(){let html=previousAccounts();let i=0;return html.replaceAll('<dd>'+badge('Sample')+'</dd>',()=>{const key=accountKeys()[i++];return `<dd>${demoConnections[key]?'<span class="badge active">Connected · demo</span>':badge('Sample')}</dd>`})};
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action?.dataset.action==='connect-info'&&['Meta','Google','LinkedIn','TikTok'].includes(action.dataset.platform)){e.stopImmediatePropagation();close();connectDemo(action.dataset.platform);return}if(action?.dataset.action==='account'){const key=accountKeys()[Number(action.dataset.id)];if(demoConnections[key]){e.stopImmediatePropagation();modal('Connected sample account',esc(key),`<dl class="detail-list"><div><dt>Status</dt><dd>Connected · demo</dd></div><div><dt>Authorized access</dt><dd>${esc(demoConnections[key])}</dd></div><div><dt>Data source</dt><dd>Illustrative sample data</dd></div></dl><div class="inline-note">No real authorization or token exists. Disconnecting resets this walkthrough status; sample campaigns remain available.</div><div class="modal-actions"><button data-action="account-route" data-id="${Number(action.dataset.id)}">Configure network</button><button data-connect="disconnect" data-key="${esc(key)}">Disconnect demo account</button></div>`);return}}if(action?.dataset.action==='confirm-reset'){for(const k of Object.keys(demoConnections))delete demoConnections[k];persistConnections()}const b=e.target.closest('[data-connect]');if(!b)return;const f=connectionFlow;switch(b.dataset.connect){case'deny':close();toast('Access declined. No demo accounts were connected.');break;case'authorize':f.access=$('#connection-access').value;f.step=2;drawConnection();break;case'back':f.selected=[...document.querySelectorAll('[name="connection-account"]:checked')].map(x=>x.value);f.step=1;drawConnection();break;case'finish':f.selected=[...document.querySelectorAll('[name="connection-account"]:checked')].map(x=>x.value);if(!f.selected.length){$('#connection-error').textContent='Select at least one account to continue.';return}for(const key of f.selected)demoConnections[key]=f.access;persistConnections();record(`${f.platform} · ${f.selected.length} sample accounts linked (${f.access.toLowerCase()})`);f.step=3;render();drawConnection();break;case'done':close();go('accounts');break;case'disconnect':delete demoConnections[b.dataset.key];persistConnections();record(`${b.dataset.key} · demo connection removed`);close();render();toast('Demo account disconnected. Sample campaigns retained.');break}},true);
document.addEventListener('change',e=>{if(e.target.id==='connection-access')$('#write-permission').textContent=e.target.value==='Campaign management'?'Create and update campaigns and budgets':'No permission to change campaigns or budgets'});
render();
